let dados=[];const rows=document.getElementById('rows');function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}async function load(){dados=await apiFetch('/operacoes/admin/categorias');rows.innerHTML=dados.length?dados.map(c=>`<tr><td><input data-n="${c.id}" value="${esc(c.nome)}"></td><td><input data-s="${c.id}" value="${esc(c.slug)}"></td><td>${c.produtos}</td><td><button onclick="save(${c.id})">Guardar</button> <button onclick="delCat(${c.id})">Apagar</button></td></tr>`).join(''):'<tr><td colspan="4">Ainda não existem categorias.</td></tr>'}async function save(id){const n=document.querySelector(`[data-n="${id}"]`).value,s=document.querySelector(`[data-s="${id}"]`).value;try{await apiFetch('/operacoes/admin/categorias/'+id,{method:'PUT',body:JSON.stringify({nome:n,slug:s})});await load()}catch(e){alert(e.message)}}async function delCat(id){if(!confirm('Apagar esta categoria? Produtos associados ficarão sem categoria.'))return;try{await apiFetch('/operacoes/admin/categorias/'+id,{method:'DELETE'});await load()}catch(e){alert(e.message)}}document.getElementById('guardar').onclick=async()=>{try{await apiFetch('/operacoes/admin/categorias',{method:'POST',body:JSON.stringify({nome:nome.value,slug:slug.value,descricao:desc.value})});nome.value='';slug.value='';desc.value='';msg.textContent='Categoria criada.';load()}catch(e){msg.textContent=e.message}};load().catch(e=>rows.innerHTML=`<tr><td colspan="4">${esc(e.message)}</td></tr>`);
